{
  "type": "object",
  "properties": {
    "recommendation": {
      "type": "string",
      "enum": [
        "open_investigation",
        "no_case",
        "hold_for_review"
      ],
      "description": "Recommended next step."
    },
    "anomaly_type": {
      "type": "string",
      "enum": [
        "meter_tamper_events",
        "possible_bypass",
        "reverse_energy",
        "stopped_or_slow_meter",
        "unbilled_consumption",
        "other"
      ],
      "description": "What the meter data shows."
    },
    "evidence_event_ids": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Meter event ids the case rests on, from the tools."
    },
    "anomaly_start": {
      "type": [
        "string",
        "null"
      ],
      "description": "ISO date of the first relevant event."
    },
    "baseline_kwh_per_day": {
      "type": "number",
      "description": "Baseline daily kWh before anomaly_start."
    },
    "observed_kwh_per_day": {
      "type": "number",
      "description": "Average daily kWh since anomaly_start."
    },
    "estimated_loss_kwh": {
      "type": "number",
      "description": "Estimated unbilled kWh since anomaly_start."
    },
    "estimated_loss_amount": {
      "type": "number",
      "description": "Estimated unbilled amount at the tariff rate."
    },
    "medical_flag": {
      "type": "boolean",
      "description": "The premise is medical-baseline or life-support."
    },
    "ordinary_explanations_checked": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Ordinary explanations ruled out."
    },
    "case_summary": {
      "type": "string",
      "description": "Neutral description of the meter data for the field investigator. No accusation."
    },
    "confidence": {
      "type": "number",
      "description": "0 to 1. How sure you are that the recommendation is right given what the tools returned. Below 0.5 means you are guessing."
    },
    "rationale": {
      "type": "string",
      "description": "Two to five sentences a reviewer can check against the tool results. Cite the record ids you relied on."
    },
    "questions_for_human": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "If a person has to decide, the specific questions they need to answer. Empty when nothing is open."
    }
  },
  "required": [
    "recommendation",
    "anomaly_type",
    "evidence_event_ids",
    "anomaly_start",
    "baseline_kwh_per_day",
    "observed_kwh_per_day",
    "estimated_loss_kwh",
    "estimated_loss_amount",
    "medical_flag",
    "ordinary_explanations_checked",
    "case_summary",
    "confidence",
    "rationale",
    "questions_for_human"
  ],
  "additionalProperties": false
}

parameters.jsCode:
// Deterministic checks. The agent's output is a proposal; nothing here trusts it
// without comparing against config or a fresh read of the system of record.
const cfg = $('Config').first().json;
// n8n links each item back to the request it came from. That link can break after the AI
// Agent node (seen live), so fall back to the node's output when it holds exactly one item,
// which cannot be ambiguous.
const one = (name) => { try { return $(name).item.json; } catch (e) { const all = $(name).all(); if (all.length === 1) return all[0].json; throw e; } };
let out = null;
try { out = one('Revenue protection agent').output ?? null; } catch (e) {} // unreadable output is treated as none

const reasons = [];
if (!out) reasons.push('agent_produced_no_valid_output');
if (out && !(typeof out.confidence === 'number' && out.confidence >= cfg.min_confidence)) {
  reasons.push('confidence ' + out?.confidence + ' below ' + cfg.min_confidence);
}

const req = one('Normalize candidate'); // one(): defined by guardPreamble; survives a lost item link
const d = $json; // fresh meter events, daily reads, flags and tariff for the premise
const rec = out?.recommendation;
const noop = rec === 'no_case';
const events = d.meter_events ?? [];
const eventIds = new Set(events.map((e) => e.event_id));
const medical = d.flags?.medical_baseline === true || d.flags?.life_support === true;
const round2 = (n) => Math.round(n * 100) / 100;

// Estimated loss, recomputed from the daily reads (estimated reads left out).
const start = out?.anomaly_start ? String(out.anomaly_start).slice(0, 10) : null;
const reads = (d.daily_reads ?? []).filter((r) => !r.estimated).map((r) => ({ date: String(r.date).slice(0, 10), kwh: Number(r.kwh) }));
const startMs = start ? Date.parse(start) : NaN;
const before = reads.filter((r) => r.date < start && Date.parse(r.date) >= startMs - cfg.baseline_days * 86400000);
const after = reads.filter((r) => r.date >= start);
const avg = (rs) => (rs.length ? rs.reduce((s, r) => s + r.kwh, 0) / rs.length : 0);
const baseline = avg(before);
const observed = avg(after);
const lossKwh = round2(Math.max(0, baseline - observed) * after.length);
const lossAmount = round2(lossKwh * Number(d.tariff_rate_per_kwh ?? 0));

if (d.meter_id && d.meter_id !== req.meter_id) reasons.push('premise ' + req.premise_id + ' now has meter ' + d.meter_id + ', not ' + req.meter_id);
if (rec === 'hold_for_review') reasons.push('agent asks for review');
if (d.open_investigation_id) reasons.push('investigation ' + d.open_investigation_id + ' is already open at this premise');

if (rec === 'open_investigation') {
  const cited = out.evidence_event_ids ?? [];
  if (!cited.length) reasons.push('case cites no meter events');
  const unknown = cited.filter((id) => !eventIds.has(id));
  if (unknown.length) reasons.push('case cites meter events the system does not return: ' + unknown.join(', '));
  if (!start || Number.isNaN(startMs)) reasons.push('case has no anomaly start date');
  if (!before.length || !after.length) reasons.push('not enough actual reads either side of ' + start + ' to estimate a loss');
  if (!(Number(d.tariff_rate_per_kwh) > 0)) reasons.push('no tariff rate on the account');
  const diff = Math.abs(Number(out.estimated_loss_kwh) - lossKwh);
  if (diff > Math.max(1, lossKwh * cfg.loss_estimate_tolerance)) reasons.push('agent estimated ' + out.estimated_loss_kwh + ' kWh, meter data gives ' + lossKwh + ' kWh');
  if (lossAmount < cfg.min_loss_amount) reasons.push('recomputed loss ' + lossAmount + ' is below the case threshold of ' + cfg.min_loss_amount);
  const text = String(out.case_summary ?? '').toLowerCase();
  const words = ["theft","thief","steal","stole","fraud","illegal","criminal","guilty","tampered by","the customer is"].filter((w) => text.includes(w));
  if (words.length) reasons.push('case summary uses accusatory language (' + words.join(', ') + '). Rewrite in terms of the meter data');
}

const medicalLine = medical ? ':warning: *MEDICAL BASELINE / LIFE SUPPORT premise.* Field staff must not disconnect or interrupt supply.\n' : '';
const action = {
  type: 'field_investigation',
  candidate_id: req.candidate_id,
  premise_id: req.premise_id,
  meter_id: req.meter_id,
  medical_flag: medical,
  anomaly_type: out?.anomaly_type ?? null,
  anomaly_start: start,
  evidence_event_ids: out?.evidence_event_ids ?? [],
  baseline_kwh_per_day: round2(baseline),
  observed_kwh_per_day: round2(observed),
  estimated_loss_kwh: lossKwh,
  estimated_loss_amount: lossAmount,
  case_summary: out?.case_summary ?? '',
  customer_contact: false,
};
const summary = medicalLine
  + 'Candidate ' + req.candidate_id + ' · premise ' + req.premise_id + ' · meter ' + req.meter_id + ' (' + req.rule + ')\n'
  + 'Meter data: ' + action.anomaly_type + ' from ' + start + '. ' + action.evidence_event_ids.length + ' meter events cited.\n'
  + 'Daily kWh ' + action.baseline_kwh_per_day + ' before, ' + action.observed_kwh_per_day + ' since. Estimated unbilled ' + lossKwh + ' kWh, ' + lossAmount + ' (recomputed).\n'
  + 'Proposed: field investigation. No customer contact.\n' + (out?.rationale ?? '');
const ok = reasons.length === 0;
const isNoop = typeof noop !== 'undefined' && noop === true;
const route = !ok ? 'escalate' : isNoop ? 'none' : 'approve';
return { json: { business_key: req.business_key, route, guardrail_reasons: reasons, action, approval_summary: summary, planned_actions: ok && !isNoop ? [action] : [] } };

// The approval request goes to one named person, so the approver is that person.
// Slack returns { data: { approved, respondedAt } }; a timeout resumes without it.
const cfg = $('Config').first().json;
const approved = $json.data?.approved;
return {
  json: {
    decision: approved === true ? 'approved' : approved === false ? 'declined' : 'timed_out',
    approver: cfg.approver_slack_user,
    decided_at: $json.data?.respondedAt ?? new Date().toISOString(),
    handoff_reason: approved === true || approved === false ? '' : 'approval timed out after ' + cfg.approval_timeout_hours + ' hours',
  },
};

// Done only when the system of record shows what was planned.
// Read the plan even if n8n lost the item link (seen live after the AI Agent node).
const one = (name) => { try { return $(name).item.json; } catch (e) { const all = $(name).all(); if (all.length === 1) return all[0].json; throw e; } };
const planned = one('Guardrails').action;
const inv = $json.investigation ?? {};
const ok = $json.status === 'dispatched' && inv.premise_id === planned.premise_id && inv.type === 'field_investigation'
  && inv.medical_flag === planned.medical_flag && inv.customer_contact !== true;
const detail = 'candidate shows ' + $json.status + ', investigation ' + JSON.stringify({ premise_id: inv.premise_id, type: inv.type, medical_flag: inv.medical_flag, customer_contact: inv.customer_contact })
  + '; expected dispatched field_investigation at ' + planned.premise_id + ' with medical_flag ' + planned.medical_flag + ' and no customer contact';
return { json: { verified: ok, verify_failed: !ok, verify_detail: ok ? '' : detail } };

// Collects everything a reviewer needs in one record: the request, what the agent
// proposed, why the guardrails stopped it, and the tool calls behind it.
// Every lookup is guarded: this node is the safety net, so it must never be the step that fails.
// n8n links each item back to the request it came from. That link can break after the AI
// Agent node (seen live), so fall back to the node's output when it holds exactly one item,
// which cannot be ambiguous.
const one = (name) => { try { return $(name).item.json; } catch (e) { const all = $(name).all(); if (all.length === 1) return all[0].json; throw e; } };
let intake = null;
let agent = null;
let guard = null;
try { intake = one('Normalize candidate'); } catch (e) {}
try { agent = one('Revenue protection agent'); } catch (e) {}
try { guard = one('Guardrails'); } catch (e) {}

const reasons = [...(guard?.guardrail_reasons ?? [])];
if (!intake) {
  // n8n could not link this item back to its request. Keep whatever identifies it and say so.
  intake = { business_key: $json.business_key ?? null };
  reasons.push('item_context_lost: the request could not be linked to this failure; check the n8n execution');
}
if ($json.error) reasons.push('system_error: ' + ($json.error.message ?? JSON.stringify($json.error)).slice(0, 300));
if ($json.verify_failed) reasons.push('verification_failed: ' + $json.verify_detail);
if ($json.handoff_reason) reasons.push($json.handoff_reason);
if (!agent?.output && !reasons.length) reasons.push('agent_produced_no_valid_output');
if (!reasons.length) {
  const o = agent.output;
  reasons.push('agent recommends review: ' + (o.decision ?? o.recommended_action ?? o.classification ?? o.route_to_queue ?? 'see proposal'));
}

const REDACT = [].map((p) => new RegExp(p, 'g'));
const scrub = (text) => REDACT.reduce((t, r) => t.replace(r, '[redacted]'), String(text ?? ''));
// The masks also apply to what the model wrote, in case it repeated a number it read.
const scrubJson = (v) => {
  if (!REDACT.length || v == null) return v;
  try { return JSON.parse(scrub(JSON.stringify(v))); } catch (e) { return scrub(JSON.stringify(v)); }
};
const trace = (agent?.intermediateSteps ?? []).map((s) => ({
  tool: s.action?.tool,
  input: s.action?.toolInput,
  observation: scrub(s.observation).slice(0, 1500),
}));

const summary = 'Candidate ' + intake.candidate_id + ' · premise ' + intake.premise_id + ' · ' + intake.rule + ' · proposed ' + (agent?.output?.recommendation ?? 'none');
// Slack-safe copies: request, document and model text can contain Slack markup such as <!channel>.
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return {
  json: {
    business_key: intake.business_key,
    team: "revenue protection",
    reasons,
    proposed: scrubJson(agent?.output ?? null),
    confidence: agent?.output?.confidence ?? null,
    questions: scrubJson(agent?.output?.questions_for_human ?? []),
    trace,
    summary,
    slack: { key: esc(intake.business_key), summary: esc(summary), reasons: esc(reasons.join('; ')) },
  },
};

parameters.query:
INSERT INTO agent_exceptions (workflow, business_key, team, reasons, proposed_action, confidence, questions, trace, summary, n8n_execution_id)
VALUES ($1, $2, $3, $4::jsonb, $5::jsonb, $6, $7::jsonb, $8::jsonb, $9, $10)
RETURNING id;

